import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Fix an odd integer {m} ≥ 3. A positive integer k is called {m}-good if there exist positive integers a and b with a < b such that a^{m} = (k a + 1) b + k. Determine the sum of all {m}-good integers k that do not exceed {n_max}.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# Choose an odd exponent m >= 3, keeping values small enough to avoid huge intermediate numbers
m = rng.choice([3, 5, 7])
# Choose an upper bound for k; ensure at least 2 so the set of good k is nontrivial
n_max = rng.randint(200, 3000)
if n_max < 2:
    n_max = 2
return {'m': m, 'n_max': n_max}

    def verifier(assign):
# Validate presence and types
if 'm' not in assign or 'n_max' not in assign:
    # Missing slots
    return False, None  # Missing required fields
m = assign['m']
n_max = assign['n_max']
# Domain checks
if not isinstance(m, int) or not isinstance(n_max, int):
    return False, None  # Non-integer inputs
if m < 3 or m % 2 == 0:
    return False, None  # m must be odd and at least 3
if n_max < 1:
    return False, None  # Upper bound must be positive
# Core classification (proved in notes): for odd m >= 3, all k >= 2 are m-good, and k = 1 is not.
# Therefore sum = 1 + 2 + ... + n_max minus (1 if n_max >= 1 else 0)
# i.e., n_max*(n_max+1)//2 - 1.
answer = n_max * (n_max + 1) // 2 - (1 if n_max >= 1 else 0)
# Sanity checks to enforce correctness and non-triviality:
# Construct explicit witnesses (a, b) for a couple of small k values using the method from the proof.
# For k >= 2, set a = k^m and M = ka + 1 = k^(m+1) + 1, then M | (a^m - k) and b = (a^m - k)/M > a.
# Check k = 2 always (n_max >= 1 ensures 2 may be within bound; if n_max < 2 we skip but we already enforce n_max >= 1).
def check_k(k):
    if k < 2:  # skip
        return True
    # Build explicit a, M, b
    a = k ** m
    M = k * a + 1  # equals k^(m+1) + 1
    # Ensure divisibility
    rem = (a ** m - k) % M
    if rem != 0:
        return False
    b = (a ** m - k) // M
    # Check the defining relation and inequalities
    if not (a < b):
        return False
    lhs = a ** m
    rhs = (k * a + 1) * b + k
    return lhs == rhs
# Check for k = 2
if n_max >= 2 and not check_k(2):
    return False, None  # Construction failed unexpectedly
# Also check for k = 3 when available
if n_max >= 3 and not check_k(3):
    return False, None
# Check that k = 1 indeed does not admit b > 0 using the same construction (it yields b = 0)
# (This is not a full impossibility proof, but confirms the canonical construction does not trivially produce a solution.)
if n_max >= 1:
    a1 = 1 ** m
    M1 = 1 * a1 + 1
    b1_num = a1 ** m - 1
    if M1 == 0:
        return False, None  # defensive; should not happen
    b1 = b1_num // M1
    # For k=1, the construction gives b1=0; ensure we are not counting k=1.
    if b1 != 0:
        return False, None
return True, answer


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

